import Foundation

// MARK: - EventStore
//
// Authoritative local event log. The single entry point for appending events.
//
// Invariants (see EVENT_LOG_V2.md §Invariants):
//   1. Exactly ONE transaction is used per append. The events row, the
//      aggregate_revisions upsert, and the outbox rows are all committed
//      atomically. Ref: https://www.sqlite.org/isolation.html (a single
//      transaction is atomic).
//   2. `local_seq` is monotonic and unique (PRIMARY KEY). It is generated by
//      the store from MAX(local_seq)+1 under the transaction's reserved lock.
//   3. `aggregate_rev` is 1-based and per-aggregate. It is computed from
//      `aggregate_revisions.current_rev + 1`. A mismatch with the value the
//      client expected raises `AppendError.optimisticConcurrencyConflict`,
//      giving deterministic conflict behavior for concurrent writers.
//   4. Idempotency: a UNIQUE index over (venue_id, idempotency_key,
//      request_fingerprint). If the same triple arrives again, the store
//      returns the EXISTING event (same result). If the same
//      (venue_id, idempotency_key) arrives with a DIFFERENT fingerprint, it is
//      a conflict and the UNIQUE insert fails; the store maps this to
//      `AppendError.idempotencyConflict`.
//   5. NO `SELECT ... FOR UPDATE` exists. We use `BEGIN IMMEDIATE`, which
//      acquires the database RESERVED lock for the whole transaction.
//      Ref: https://www.sqlite.org/lang_transaction.html
//
public final class EventStore: @unchecked Sendable {

    public enum AppendError: Error, Equatable {
        /// The aggregate's expected revision did not match the stored one.
        case optimisticConcurrencyConflict(aggregateID: AggregateID, expected: Int64, actual: Int64)
        /// Same (venue_id, idempotency_key) with a different fingerprint.
        case idempotencyConflict(venueID: VenueID, key: IdempotencyKey, existingEventID: EventID)
        /// A different event already used this event id.
        case duplicateEventID(EventID)
        /// Something went wrong at the storage layer.
        case storage(String)
    }

    /// Result of a successful append.
    public struct AppendResult: Equatable, Sendable {
        public let event: EventRecord
        /// `true` if this append was a deduplicated replay of an existing
        /// event (idempotent retry). The returned event is the original.
        public let wasReplay: Bool
    }

    public let connection: SQLiteConnection
    private let clock: Clock

    public init(connection: SQLiteConnection, clock: Clock = SystemClock()) {
        self.connection = connection
        self.clock = clock
    }

    // MARK: - Append

    /// Appends a single event and its outbox rows in ONE transaction.
    ///
    /// - Parameter expectedRevision: For optimistic concurrency. If the
    ///   aggregate already exists, its `current_rev` must equal this value.
    ///   Pass `0` (the default) to require that the aggregate does NOT yet
    ///   exist — i.e. this is the first event for that aggregate. Passing
    ///   `nil` disables the check (last-writer-allowed, still append-only; use
    ///   only for genuinely independent events).
    public func append(_ request: AppendEventRequest,
                       expectedRevision: Int64? = 0) throws -> AppendResult {
        // First: cheap idempotency replay check (outside the write tx). If the
        // exact (venue,key,fingerprint) already exists, return the existing
        // event without writing. This is read-only.
        if let existing = try fetchByIdempotency(
            venueID: request.venueID,
            key: request.idempotencyKey,
            fingerprint: request.requestFingerprint
        ) {
            return AppendResult(event: existing, wasReplay: true)
        }

        // Check for a same-key-different-fingerprint conflict before we open a
        // write transaction. This produces a clean error instead of relying on
        // the UNIQUE index to raise SQLITE_CONSTRAINT mid-transaction.
        if let conflicting = try fetchEventIDForIdempotencyKey(
            venueID: request.venueID,
            key: request.idempotencyKey
        ) {
            throw AppendError.idempotencyConflict(
                venueID: request.venueID,
                key: request.idempotencyKey,
                existingEventID: conflicting
            )
        }

        // Perform the append inside ONE transaction. All reads + writes run
        // under a single queue acquisition (no reentrant locking).
        do {
            return try connection.transaction { tx in
                // Re-check inside the transaction to close the race between our
                // pre-check and acquiring the RESERVED lock.
                if let existing = try Self.fetchByIdempotencyInTX(
                    tx,
                    venueID: request.venueID,
                    key: request.idempotencyKey,
                    fingerprint: request.requestFingerprint
                ) {
                    return AppendResult(event: existing, wasReplay: true)
                }

                // Determine the next revision for this aggregate.
                //
                // `expectedRevision` semantics:
                //   - nil            : no optimistic-concurrency check (append-only
                //                      is still enforced; revision auto-increments).
                //   - 0              : the aggregate must NOT yet exist (first event).
                //   - N (>0)         : the aggregate's current_rev must equal N.
                let currentRev = try Self.fetchAggregateRevInTX(tx, aggregateID: request.aggregateID)
                let nextRev: Int64
                switch (currentRev, expectedRevision) {
                case (nil, nil):
                    nextRev = 1
                case (nil, 0):
                    // Caller expected the aggregate not to exist; correct. First event.
                    nextRev = 1
                case (nil, let expected?):
                    // Aggregate does not exist but caller expected a positive rev.
                    throw AppendError.optimisticConcurrencyConflict(
                        aggregateID: request.aggregateID, expected: expected, actual: 0)
                case (let existing?, nil):
                    nextRev = existing + 1
                case (let existing?, let expected?) where expected == existing:
                    nextRev = existing + 1
                case (let existing?, let expected?):
                    throw AppendError.optimisticConcurrencyConflict(
                        aggregateID: request.aggregateID,
                        expected: expected,
                        actual: existing)
                }

                // Next local_seq.
                let nextSeq = try Self.nextLocalSeqInTX(tx)
                let now = clock.nowMs()
                let occurredAt = request.occurredAtMs ?? now

                // Insert the event row.
                _ = try tx.execute(sql: """
                    INSERT INTO events (
                        event_id, local_seq, venue_id, aggregate_id, aggregate_type,
                        aggregate_rev, event_type, payload_version, payload,
                        request_fingerprint, idempotency_key, device_id,
                        occurred_at_ms, logged_at_ms
                    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?);
                    """, params: [
                        .text(request.eventID.rawValue),
                        .integer(nextSeq),
                        .text(request.venueID.rawValue),
                        .text(request.aggregateID.rawValue),
                        .text(request.aggregateType),
                        .integer(nextRev),
                        .text(request.eventType),
                        .integer(Int64(request.payloadVersion)),
                        .blob(request.payload),
                        .text(request.requestFingerprint),
                        .text(request.idempotencyKey.rawValue),
                        .text(request.deviceID.rawValue),
                        .integer(occurredAt),
                        .integer(now)
                    ])

                // Upsert aggregate revision. We use INSERT ... ON CONFLICT so the
                // same statement handles first-event and subsequent-event cases.
                _ = try tx.execute(sql: """
                    INSERT INTO aggregate_revisions
                        (aggregate_id, aggregate_type, venue_id, current_rev, current_seq)
                    VALUES (?,?,?,?,?)
                    ON CONFLICT(aggregate_id) DO UPDATE SET
                        current_rev = excluded.current_rev,
                        current_seq = excluded.current_seq;
                    """, params: [
                        .text(request.aggregateID.rawValue),
                        .text(request.aggregateType),
                        .text(request.venueID.rawValue),
                        .integer(nextRev),
                        .integer(nextSeq)
                    ])

                // Outbox rows: one per target, default state 'pending'.
                for target in request.outboxTargets {
                    _ = try tx.execute(sql: """
                        INSERT INTO outbox
                            (event_seq, target, state, attempts, next_attempt_ms,
                             lease_owner, lease_expires_ms, last_error, ack_token,
                             updated_at_ms)
                        VALUES (?,?, 'pending', 0, ?, NULL, NULL, NULL, NULL, ?);
                        """, params: [
                            .integer(nextSeq),
                            .text(target.rawValue),
                            .integer(now),  // next_attempt_ms = now (immediately due)
                            .integer(now)
                        ])
                }

                let record = EventRecord(
                    eventID: request.eventID,
                    localSeq: nextSeq,
                    venueID: request.venueID,
                    aggregateID: request.aggregateID,
                    aggregateType: request.aggregateType,
                    aggregateRev: nextRev,
                    eventType: request.eventType,
                    payloadVersion: request.payloadVersion,
                    payload: request.payload,
                    requestFingerprint: request.requestFingerprint,
                    idempotencyKey: request.idempotencyKey,
                    deviceID: request.deviceID,
                    occurredAtMs: occurredAt,
                    loggedAtMs: now
                )
                return AppendResult(event: record, wasReplay: false)
            }
        } catch let error as AppendError {
            throw error
        } catch let SQLiteConnection.Error.execFailed(message)
                where Self.isUniqueEventIDViolation(message) {
            throw AppendError.duplicateEventID(request.eventID)
        } catch let SQLiteConnection.Error.stepFailed(message)
                where Self.isUniqueEventIDViolation(message) {
            throw AppendError.duplicateEventID(request.eventID)
        } catch let SQLiteConnection.Error.execFailed(message)
                where message.contains("idx_events_idempotency") {
            // Lost the race: another writer inserted the same key between our
            // pre-check and commit. Report as conflict.
            throw AppendError.idempotencyConflict(
                venueID: request.venueID,
                key: request.idempotencyKey,
                existingEventID: request.eventID)
        } catch let SQLiteConnection.Error.stepFailed(message)
                where message.contains("idx_events_idempotency") {
            throw AppendError.idempotencyConflict(
                venueID: request.venueID,
                key: request.idempotencyKey,
                existingEventID: request.eventID)
        } catch {
            throw AppendError.storage(String(describing: error))
        }
    }

    private static func isUniqueEventIDViolation(_ message: String) -> Bool {
        message.contains("UNIQUE constraint failed: events.event_id")
    }

    // MARK: - Reads

    public func event(localSeq: Int64) throws -> EventRecord? {
        try connection.query(
            sql: "SELECT * FROM events WHERE local_seq = ?;",
            params: [.integer(localSeq)],
            mapper: EventStore.rowToEventStatic
        ).first
    }

    public func event(eventID: EventID) throws -> EventRecord? {
        try connection.query(
            sql: "SELECT * FROM events WHERE event_id = ?;",
            params: [.text(eventID.rawValue)],
            mapper: EventStore.rowToEventStatic
        ).first
    }

    /// All events for an aggregate, ordered by revision.
    public func events(forAggregate id: AggregateID) throws -> [EventRecord] {
        try connection.query(
            sql: "SELECT * FROM events WHERE aggregate_id = ? ORDER BY aggregate_rev;",
            params: [.text(id.rawValue)],
            mapper: EventStore.rowToEventStatic
        )
    }

    /// Events for a venue in local-seq order, optionally after a checkpoint.
    public func events(forVenue id: VenueID, afterSeq: Int64 = 0) throws -> [EventRecord] {
        try connection.query(
            sql: "SELECT * FROM events WHERE venue_id = ? AND local_seq > ? ORDER BY local_seq;",
            params: [.text(id.rawValue), .integer(afterSeq)],
            mapper: EventStore.rowToEventStatic
        )
    }

    public func currentRevision(forAggregate id: AggregateID) throws -> Int64? {
        try connection.query(
            sql: "SELECT current_rev FROM aggregate_revisions WHERE aggregate_id = ?;",
            params: [.text(id.rawValue)],
            mapper: { $0.int(0) }
        ).first
    }

    /// The highest local_seq currently persisted. Useful for resumable sync.
    public func maxLocalSeq() throws -> Int64 {
        let rows = try connection.query(
            sql: "SELECT COALESCE(MAX(local_seq), 0) FROM events;",
            mapper: { $0.int(0) }
        )
        return rows.first ?? 0
    }

    // MARK: - Internal helpers

    // MARK: - TX-scoped helpers (inline, no reentrant queue lock)
    //
    // These static helpers take a `TX` and execute reads inline within an
    // open transaction. They must only be called from inside
    // `connection.transaction { tx in ... }`.

    fileprivate static func nextLocalSeqInTX(_ tx: SQLiteConnection.TX) throws -> Int64 {
        try tx.queryOne(
            sql: "SELECT COALESCE(MAX(local_seq), 0) + 1 FROM events;",
            mapper: { $0.int(0) }
        ) ?? 1
    }

    fileprivate static func fetchAggregateRevInTX(_ tx: SQLiteConnection.TX,
                                                   aggregateID: AggregateID) throws -> Int64? {
        try tx.queryOne(
            sql: "SELECT current_rev FROM aggregate_revisions WHERE aggregate_id = ?;",
            params: [.text(aggregateID.rawValue)],
            mapper: { $0.int(0) }
        )
    }

    fileprivate static func fetchByIdempotencyInTX(_ tx: SQLiteConnection.TX,
                                                    venueID: VenueID,
                                                    key: IdempotencyKey,
                                                    fingerprint: String) throws -> EventRecord? {
        try tx.queryOne(
            sql: """
            SELECT * FROM events
             WHERE venue_id = ? AND idempotency_key = ? AND request_fingerprint = ?
             LIMIT 1;
            """,
            params: [.text(venueID.rawValue), .text(key.rawValue), .text(fingerprint)],
            mapper: EventStore.rowToEventStatic
        )
    }

    // MARK: - Non-transactional helpers (used by the pre-checks outside the tx)

    private func fetchByIdempotency(venueID: VenueID, key: IdempotencyKey,
                                    fingerprint: String) throws -> EventRecord? {
        try connection.query(
            sql: """
            SELECT * FROM events
             WHERE venue_id = ? AND idempotency_key = ? AND request_fingerprint = ?
             LIMIT 1;
            """,
            params: [.text(venueID.rawValue), .text(key.rawValue), .text(fingerprint)],
            mapper: EventStore.rowToEventStatic
        ).first
    }

    private func fetchEventIDForIdempotencyKey(venueID: VenueID, key: IdempotencyKey) throws -> EventID? {
        try connection.query(
            sql: """
            SELECT event_id FROM events
             WHERE venue_id = ? AND idempotency_key = ?
             LIMIT 1;
            """,
            params: [.text(venueID.rawValue), .text(key.rawValue)],
            mapper: { EventID(rawValue: $0.string(0) ?? "") }
        ).first
    }

    fileprivate static func rowToEventStatic(_ row: StatementRow) -> EventRecord {
        EventRecord(
            eventID: EventID(rawValue: row.string(0) ?? ""),
            localSeq: row.int(1),
            venueID: VenueID(rawValue: row.string(2) ?? ""),
            aggregateID: AggregateID(rawValue: row.string(3) ?? ""),
            aggregateType: row.string(4) ?? "",
            aggregateRev: row.int(5),
            eventType: row.string(6) ?? "",
            payloadVersion: Int(row.int(7)),
            payload: row.data(8) ?? Data(),
            requestFingerprint: row.string(9) ?? "",
            idempotencyKey: IdempotencyKey(rawValue: row.string(10) ?? ""),
            deviceID: DeviceID(rawValue: row.string(11) ?? ""),
            occurredAtMs: row.int(12),
            loggedAtMs: row.int(13)
        )
    }
}
